package pe.nexo.store.shared;import org.springframework.http.*;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import pe.nexo.store.product.ProductNotFoundException;import java.time.LocalDateTime;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{private ResponseEntity<ApiError>error(HttpStatus status,String message,Map<String,String>errors){return ResponseEntity.status(status).body(new ApiError(LocalDateTime.now(),status.value(),message,errors));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError>validation(MethodArgumentNotValidException ex){Map<String,String>errors=new LinkedHashMap<>();ex.getBindingResult().getFieldErrors().forEach(e->errors.put(e.getField(),e.getDefaultMessage()));return error(HttpStatus.BAD_REQUEST,"Datos invalidos",errors);}@ExceptionHandler(HttpMessageNotReadableException.class)ResponseEntity<ApiError>malformed(){return error(HttpStatus.BAD_REQUEST,"El cuerpo JSON no es valido",Map.of());}@ExceptionHandler(ResponseStatusException.class)ResponseEntity<ApiError>status(ResponseStatusException ex){return error(HttpStatus.valueOf(ex.getStatusCode().value()),ex.getReason()==null?"No se pudo completar la operacion":ex.getReason(),Map.of());}@ExceptionHandler({ProductNotFoundException.class,IllegalArgumentException.class})ResponseEntity<ApiError>notFound(RuntimeException ex){return error(HttpStatus.NOT_FOUND,ex.getMessage(),Map.of());}@ExceptionHandler(IllegalStateException.class)ResponseEntity<ApiError>conflict(IllegalStateException ex){return error(HttpStatus.CONFLICT,ex.getMessage(),Map.of());}@ExceptionHandler(Exception.class)ResponseEntity<ApiError>unexpected(){return error(HttpStatus.INTERNAL_SERVER_ERROR,"El servidor no pudo completar la operacion",Map.of());}}
